export interface TavernParseResult {
  /** 输入格式：png-embed（PNG 内嵌）或 json（独立 JSON 文件）。 */
  kind: 'png-embed' | 'json'
  /** 角色卡 spec 版本（如 chara_card_v2）；旧版无 spec。 */
